struct MyVenue: Codable, Sendable, Hashable {
    var id: String
    var building: VenueBuilding
    var currency: String
    var phone: String?
    var website: String?
    var sports: [VenueSport]

    init(id: String, building: VenueBuilding = VenueBuilding(), currency: String = "", phone: String? = nil, website: String? = nil, sports: [VenueSport] = []) {
        self.id = id
        self.building = building
        self.currency = currency
        self.phone = phone
        self.website = website
        self.sports = sports
    }

    init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: WireKey.self)
        id = try container.wireRequired(String.self, "id")
        building = try container.wire(VenueBuilding.self, "building") ?? VenueBuilding()
        currency = try container.wire(String.self, "currency") ?? ""
        phone = try container.wire(String.self, "phone")
        website = try container.wire(String.self, "website")
        sports = try container.wire([VenueSport].self, "sports") ?? []
    }

    func encode(to encoder: any Encoder) throws {
        var container = encoder.container(keyedBy: WireKey.self)
        try container.wire(id, "id")
        try container.wire(building, "building", default: VenueBuilding())
        try container.wire(currency, "currency", default: "")
        try container.wireOptional(phone, "phone")
        try container.wireOptional(website, "website")
        try container.wire(sports, "sports", default: [])
    }
}
